package com.example.productinventory.controller;
import com.example.productinventory.dto.ProductRequest; import com.example.productinventory.model.Product; import com.example.productinventory.service.ProductService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder; import java.net.URI; import java.util.List;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductService service; public ProductController(ProductService s){service=s;} @PostMapping public ResponseEntity<Product> create(@Valid @RequestBody ProductRequest r){Product p=service.createProduct(r);URI u=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(p.getId()).toUri();return ResponseEntity.created(u).body(p);} @GetMapping public ResponseEntity<List<Product>> all(){return ResponseEntity.ok(service.getAllProducts());} @GetMapping("/{id}") public ResponseEntity<Product> get(@PathVariable Long id){return ResponseEntity.ok(service.getProductById(id));} @PutMapping("/{id}") public ResponseEntity<Product> update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return ResponseEntity.ok(service.updateProduct(id,r));} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.deleteProduct(id);return ResponseEntity.noContent().build();} }